-- Neon Postgres schema for the espresso dial-in app.
-- Connect through Neon's pooled (-pooler) DSN; PgBouncer runs in transaction mode.
-- Derived values (dose, yield, ratio, retained water) are generated by Postgres
-- so client and server cannot drift. Raw scale readings are the source of truth.

create extension if not exists pgcrypto;

create table users (
  id           uuid primary key default gen_random_uuid(),
  auth_subject text not null unique,          -- Clerk user id (user_xxx)
  email        text,
  created_at   timestamptz not null default now()
);

create table beans (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references users(id) on delete cascade,
  name        text not null,
  roaster     text,
  origin      text,
  roast_date  date,
  archived_at timestamptz,
  created_at  timestamptz not null default now(),
  unique (id, user_id)                        -- target for logs' composite FK (ownership check)
);
create index beans_user_idx on beans (user_id, created_at desc);

create table logs (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references users(id) on delete cascade,
  bean_id       uuid,                         -- must belong to the same user: see composite FK below
  client_id     uuid not null,                -- generated by the client at wizard start; makes POST idempotent

  -- raw scale readings (grams). No fixed basket weights are assumed.
  portafilter_empty_g numeric(7,2) not null,
  portafilter_dry_g   numeric(7,2) not null,
  cup_empty_g         numeric(7,2) not null,
  cup_full_g          numeric(7,2) not null,
  portafilter_wet_g   numeric(7,2),           -- wizard step 5 may be skipped

  -- derived by Postgres
  dose_g  numeric(7,2) generated always as (portafilter_dry_g - portafilter_empty_g) stored,
  yield_g numeric(7,2) generated always as (cup_full_g - cup_empty_g) stored,
  ratio   numeric(6,3) generated always as (
            round((cup_full_g - cup_empty_g) / nullif(portafilter_dry_g - portafilter_empty_g, 0), 3)
          ) stored,
  retained_water_g numeric(7,2) generated always as (portafilter_wet_g - portafilter_dry_g) stored,

  shot_time_s    numeric(5,1),
  taste          text check (taste in ('sour','balanced','bitter')),
  grind_external numeric(5,1),                -- machine's external grind setting
  burr_internal  numeric(5,1),                -- internal burr adjustment
  notes          text,
  created_at     timestamptz not null default now(),

  constraint logs_dose_pos   check (portafilter_dry_g > portafilter_empty_g),
  constraint logs_yield_pos  check (cup_full_g > cup_empty_g),
  constraint logs_wet_ge_dry check (portafilter_wet_g is null or portafilter_wet_g >= portafilter_dry_g),
  unique (user_id, client_id),

  -- A log can only reference a bean owned by the same user (prevents IDOR via bean_id).
  -- bean_id null skips the check (MATCH SIMPLE). The column list on SET NULL needs
  -- Postgres 15+ (I'm not certain which version the Neon project will use; confirm
  -- before applying) and stops user_id from being nulled when a bean is deleted.
  foreign key (bean_id, user_id) references beans (id, user_id) on delete set null (bean_id)
);
create index logs_user_created_idx on logs (user_id, created_at desc);
create index logs_user_bean_idx    on logs (user_id, bean_id, created_at desc);

-- Shot category (ristretto / normale / lungo) is NOT stored. It is derived from
-- `ratio` at read time so thresholds can change without a migration.
-- Thresholds live in docs/contract/ratio-cases.json.
